    _fields_ = [('version', ctypes.c_uint32), ('pid', ctypes.c_int)]


class Data(ctypes.Structure):
    _fields_ = [('effective', ctypes.c_uint32), ('permitted', ctypes.c_uint32), ('inheritable', ctypes.c_uint32)]


def outcome(name, rc):
    print('%s %s' % (name, 'ok' if rc == 0 else errno.errorcode.get(ctypes.get_errno(), str(ctypes.get_errno()))))


def probe(name, args):
    if name == 'prctl':
        rc = libc.prctl(int(args[0]), ctypes.c_ulong(int(args[1]) if len(args) > 1 else 0), ctypes.c_ulong(0),
                        ctypes.c_ulong(0), ctypes.c_ulong(0))
    elif name == 'capset':
        header, data = Header(0x20080522, 0), (Data * 2)()
        rc = libc.syscall(125, ctypes.byref(header), data)          # capget
        if rc == 0:
            rc = libc.syscall(126, ctypes.byref(header), data)      # capset
    elif name == 'setgroups':
        groups = (ctypes.c_uint32 * 1)(os.getgid())
        rc = libc.setgroups(ctypes.c_size_t(1), groups)
    elif name == 'setresgid':
        gid = os.getgid()
        rc = libc.setresgid(gid, gid, gid)
    elif name == 'setresuid':
        uid = os.getuid()
        rc = libc.setresuid(uid, uid, uid)
    else:
        raise AssertionError(name)
    outcome(name, rc)


def status():
    fields = {}
    with open('/proc/self/status') as handle:
        for line in handle:
            key, _, value = line.partition(':')
            if key in KEYS:
                fields[key] = ','.join(value.split())
    print(' '.join('%s=%s' % (key, fields.get(key, '?')) for key in KEYS))


if __name__ == '__main__':
    if sys.argv[1] == 'probe':
        probe(sys.argv[2], sys.argv[3:])
    else:
        status()

