# SPDX-License-Identifier: MIT
# Trusted observer for IPC fixtures (pane 214): /proc/sysvipc rows, POSIX object
# metadata through libc (ctypes), exact-diagnostic checks and IPC_RMID controls.
# Never runs the candidate.
# Usage:
#   ipcobs.py sysv msg|sem|shm ID          stable columns of that id, or "absent"
#   ipcobs.py posix shm|sem|mq NAME        size/value/attributes, mode, uid, gid, or "absent"
#   ipcobs.py unlink shm|sem|mq NAME       libc *_unlink (fixture cleanup)
#   ipcobs.py expect LABEL CODE WANT STDERR KIND [present:ID|absent:ID]...
#                                          o.txt empty, e.txt == STDERR, status == WANT, membership
#   ipcobs.py rmid msg|sem|shm ID          libc IPC_RMID control call (exit 0 on success)
#   ipcobs.py calls LOG [WANTFILE]         recorded msgctl/semctl/shmctl argument tuples, then delete LOG;
#                                          with WANTFILE: must equal its content (control record)
import ctypes, errno, json, os, stat, sys

libc = ctypes.CDLL(None, use_errno=True)
STABLE = {'msg': ['key', 'perms', 'cbytes', 'qnum', 'uid', 'gid', 'cuid', 'cgid'],
          'sem': ['key', 'perms', 'nsems', 'uid', 'gid', 'cuid', 'cgid'],
          'shm': ['key', 'perms', 'size', 'nattch', 'uid', 'gid', 'cuid', 'cgid']}
IDCOL = {'msg': 'msqid', 'sem': 'semid', 'shm': 'shmid'}


def sysv_row(kind, ident):
    with open('/proc/sysvipc/' + kind) as handle:
        header = handle.readline().split()
        for line in handle:
            row = dict(zip(header, line.split()))
            if row[IDCOL[kind]] == str(ident):
                return row
    return None


class MqAttr(ctypes.Structure):
    _fields_ = [('mq_flags', ctypes.c_long), ('mq_maxmsg', ctypes.c_long), ('mq_msgsize', ctypes.c_long),
                ('mq_curmsgs', ctypes.c_long), ('pad', ctypes.c_long * 4)]


def posix(kind, name):
    if kind == 'shm':
        path = '/dev/shm/' + name[1:]
        if not os.path.exists(path):
            return 'absent'
        info = os.stat(path)
        extra = 'size=%d' % info.st_size
    elif kind == 'sem':
        path = '/dev/shm/sem.' + name[1:]
        if not os.path.exists(path):
            return 'absent'
        info = os.stat(path)
        libc.sem_open.restype = ctypes.c_void_p
        sem = libc.sem_open(name.encode(), 0)
        value = ctypes.c_int(-1)
        libc.sem_getvalue(ctypes.c_void_p(sem), ctypes.byref(value))
        libc.sem_close(ctypes.c_void_p(sem))
        extra = 'value=%d file=sem.%s' % (value.value, name[1:])
    else:
        fd = libc.mq_open(name.encode(), os.O_RDONLY)
        if fd < 0:
            return 'absent' if ctypes.get_errno() == errno.ENOENT else 'error %d' % ctypes.get_errno()
        attr = MqAttr()
        libc.mq_getattr(fd, ctypes.byref(attr))
        info = os.fstat(fd)
        os.close(fd)
        defaults = [open('/proc/sys/fs/mqueue/%s' % k).read().split()[0] for k in ('msg_default', 'msgsize_default')]
        extra = 'maxmsg=%d msgsize=%d curmsgs=%d defaults=%s' % (attr.mq_maxmsg, attr.mq_msgsize, attr.mq_curmsgs,
                                                                 '/'.join(defaults))
    return '%s mode=%04o uid=%d gid=%d' % (extra, stat.S_IMODE(info.st_mode), info.st_uid, info.st_gid)


def main():
    command, args = sys.argv[1], sys.argv[2:]
    if command == 'sysv':
        row = sysv_row(args[0], args[1])
        print('%s %s %s' % (args[0], 'id', 'absent' if row is None else
                            ' '.join('%s=%s' % (k, row[k]) for k in STABLE[args[0]])))
    elif command == 'posix':
        print('%s %s %s' % (args[0], args[1], posix(args[0], args[1])))
    elif command == 'unlink':
        getattr(libc, {'shm': 'shm_unlink', 'sem': 'sem_unlink', 'mq': 'mq_unlink'}[args[0]])(args[1].encode())
    elif command == 'expect':
        label, code, want, text, kind = args[:5]
        problems = []
        out, err = open('o.txt', 'rb').read(), open('e.txt', 'rb').read()
        if code != want:
            problems.append('status %s, expected %s' % (code, want))
        if out:
            problems.append('stdout %r' % out)
        if err != text.encode():
            problems.append('stderr %r, expected %r' % (err, text))
        for item in args[5:]:
            state, ident = item.split(':')
            present = sysv_row(kind, ident) is not None
            if present != (state == 'present'):
                problems.append('id %s %s' % (ident, 'present' if present else 'absent'))
        with open('observations.txt', 'a') as handle:
            handle.write('%s status=%s stdout=%r stderr=%r\n' % (label, code, out, err))
        if problems:
            print('MISMATCH %s: %s' % (label, '; '.join(problems)))
            sys.exit(1)
        print('%s ok' % label)
    elif command == 'rmid':
        kind, ident = args[0], int(args[1])
        if kind == 'msg':
            rc = libc.msgctl(ident, 0, None)
        elif kind == 'shm':
            rc = libc.shmctl(ident, 0, None)
        else:
            rc = libc.semctl(ident, 0, 0)
        sys.exit(0 if rc == 0 else 1)
    elif command == 'calls':
        path = args[0]
        rows = []
        if os.path.exists(path):
            for line in open(path):
                record = json.loads(line)
                rows.append('%s(%s)' % (record['syscall'], ','.join(
                    str(record[k]) for k in ('arg0', 'arg1', 'arg2', 'arg3') if k in record)))
            os.unlink(path)
        got = ' '.join(rows) or '-'
        if len(args) > 1:
            want = open(args[1]).read().strip()
            if got != want:
                print('MISMATCH dispatch recorded %s, libc control %s' % (got, want))
                sys.exit(1)
            print('dispatch ok')
        else:
            print(got)
    else:
        raise AssertionError(command)


if __name__ == '__main__':
    main()

